    static GUPPriceTermJournalTable find(GUPAgreementId     _agreementId,
                                         boolean            _update = false)
    {
        GUPPriceTermJournalTable gupPriceTermJournalTable;

        if (_agreementId)
        {
            if (_update)
            {
                gupPriceTermJournalTable.selectForUpdate(_update);
            }
            
            select firstonly gupPriceTermJournalTable
                index hint JournalId
                where gupPriceTermJournalTable.AgreementId == _agreementId;
            
        }

        return gupPriceTermJournalTable;
    }

    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (ret)
        {
            if (this.ValidTo && this.ValidFrom > this.ValidTo)
            {
                return checkFailed(strFmt("@GlobalUnifiedPricing:GUPPriceTermJournalTable_Validate_ToDateGtFromDate", this.AgreementId));
            }

            if (this.ValidTo && this.ValidTo < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
            {
                return checkFailed(strFmt("@GlobalUnifiedPricing:GUPPriceTermJournalTable_Validate_ToDateLtToday", this.AgreementId));
            }
        }
    
        return ret;
    }

    public boolean dateRangesOverlap(GUPPriceTermJournalTable _journalTable)
    {
        boolean ret = false;

        if (!this.ValidTo && !_journalTable.ValidTo)
        {
            ret = true;
        }
        else if (this.ValidTo)
        {
            ret = _journalTable.ValidFrom < this.ValidTo
                && (!_journalTable.ValidTo || _journalTable.ValidTo > this.ValidFrom);
        }
        else
        {
            ret = this.ValidFrom < _journalTable.ValidTo;
        }

        return ret;
    }
